<div class="top"><div><h2 style="margin:0">Invoices</h2><span class="muted"><?= (int) $due['c'] ?> unpaid · <?= e(money($due['s'])) ?> outstanding</span></div><div><a class="btn alt" href="/staff/credit-notes">Credit notes</a> <a class="btn" href="/staff/invoices/new">+ New invoice</a></div></div>
