<div class="card"><div class="tw"><table><tr><th>Number</th><th>Customer</th><th>Order</th><th>Issued</th><th>Due</th><th class="right">Total</th><th class="right">Balance</th><th>Status</th></tr>
<?php foreach ($rows as $r): $od = $r['status'] === 'issued' && $r['due_date'] < date('Y-m-d'); ?>
<tr><td><a href="/staff/invoices/<?= (int) $r['id'] ?>"><?= e($r['number']) ?></a><?= $r['kind'] === 'proforma' ? ' ' . badge('Pro-forma') : '' ?></td><td><?= e($r['bill_name']) ?></td><td><?= $r['ref'] ? '<a href="/staff/requests/' . (int) $r['request_id'] . '">' . e($r['ref']) . '</a>' : '—' ?></td><td><?= e(fmt_date($r['issue_date'])) ?></td><td class="<?= $od ? 'overdue' : '' ?>"><?= e(fmt_date($r['due_date'])) ?><?= $od ? ' (overdue)' : '' ?></td><td class="right"><?= e(money($r['total'])) ?></td><td class="right"><?= $r['kind'] === 'tax' && $r['status'] === 'issued' ? e(money($r['total'] - $r['paid'] - $r['credited'])) : '' ?></td><td><?= badge(INVOICE_STATUSES[$r['status']], ['paid' => 'p-ok', 'void' => 'p-bad', 'issued' => 'p-warn'][$r['status']]) ?></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="8" class="muted">No invoices yet.</td></tr><?php endif; ?></table></div></div>
